<script setup lang="ts">
definePageMeta({layout:'admin',middleware:'admin-auth'})
type Row={article:any;helpful:number;notHelpful:number;total:number;helpfulRatio:number};const rows=ref<Row[]>([]),selected=ref<any|null>(null),search=ref(''),city=ref(''),category=ref(''),sort=ref('needs'),page=ref(1),total=ref(0),pageCount=ref(0),pending=ref(false),toast=ref('');const cats=['Ibadah','Panduan','Kehidupan','Sosial','Ekonomi','Bisnis','Kuliner','Transportasi','Akomodasi','Makkah','Madinah','Budaya','Sejarah','Berita / Update'];const date=(v:string|null)=>v?new Date(v).toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'}):'—';async function load(){pending.value=true;try{const r=await $fetch<any>('/api/admin/media/article-feedback',{query:{search:search.value||undefined,city:city.value||undefined,category:category.value||undefined,sort:sort.value,page:page.value,pageSize:10}});rows.value=r.data;total.value=r.meta.total;pageCount.value=r.meta.pageCount}catch(e:any){toast.value=e.data?.statusMessage||'Feedback gagal dimuat.'}finally{pending.value=false}}async function open(r:Row){try{selected.value=(await $fetch<any>(`/api/admin/media/article-feedback/${r.article.id}`)).data}catch(e:any){toast.value=e.data?.statusMessage||'Detail gagal dimuat.'}}watch([search,city,category,sort],()=>{page.value=1;load()});onMounted(load)
</script>
<template><div><PageHead title="Feedback Artikel" subtitle="Media · Interaksi"><template #actions><span class="rounded-full border border-gold-soft bg-gold-sand px-3 py-1.5 text-xs font-semibold">EDITORIAL SIGNAL</span></template></PageHead><p v-if="toast" class="mt-4 rounded-xl bg-gold-sand px-4 py-3 text-sm">{{toast}}</p><section class="mt-6 rounded-2xl border border-neutral-line bg-white p-5"><div class="grid gap-3 lg:grid-cols-4"><input v-model="search" placeholder="Cari judul artikel..." class="rounded-xl border px-3 py-2 text-sm"/><select v-model="city" class="rounded-xl border px-3 py-2 text-sm"><option value="">Semua city</option><option>GENERAL</option><option>MAKKAH</option><option>MADINAH</option></select><select v-model="category" class="rounded-xl border px-3 py-2 text-sm"><option value="">Semua kategori</option><option v-for="x in cats">{{x}}</option></select><select v-model="sort" class="rounded-xl border px-3 py-2 text-sm"><option value="needs">Perlu perhatian</option><option value="total">Total feedback</option><option value="helpful">Helpful terbanyak</option><option value="notHelpful">Not helpful terbanyak</option><option value="ratio">Rasio helpful</option></select></div></section><div class="mt-6 grid gap-6 xl:grid-cols-[minmax(0,1fr)_380px]"><section class="overflow-x-auto rounded-2xl border border-neutral-line bg-white p-5"><h2 class="font-heading text-lg font-semibold">Ringkasan Feedback <span class="text-xs font-normal text-neutral-charcoal/50">{{total}} artikel</span></h2><table class="mt-4 w-full min-w-[720px] text-left text-sm"><thead class="border-b text-xs uppercase tracking-wider text-neutral-charcoal/50"><tr><th class="pb-3">Artikel</th><th>Helpful</th><th>Not helpful</th><th>Total</th><th>Rasio</th></tr></thead><tbody><tr v-for="r in rows" :key="r.article.id" class="cursor-pointer border-b last:border-0 hover:bg-gold-sand/30" @click="open(r)"><td class="py-4"><b class="block">{{r.article.title}}</b><small class="text-neutral-charcoal/55">{{r.article.city}} · {{r.article.category}} · {{date(r.article.publishedAt)}}</small></td><td class="text-brand-green">{{r.helpful}}</td><td :class="r.notHelpful?'text-red-700 font-semibold':''">{{r.notHelpful}}</td><td>{{r.total}}</td><td><span class="rounded-full px-2 py-1 text-xs" :class="r.notHelpful>=3||r.helpfulRatio<70?'bg-red-50 text-red-700':'bg-brand-green/10 text-brand-green'">{{r.helpfulRatio}}%</span></td></tr></tbody></table><p v-if="!pending&&!rows.length" class="py-12 text-center text-sm">Belum ada feedback.</p><div v-if="pageCount>1" class="mt-4 flex gap-2 border-t pt-4"><button class="rounded-full border px-3 py-1 text-xs" :disabled="page===1" @click="page--;load()">Previous</button><button v-for="n in pageCount" :key="n" class="rounded-full border px-2 py-1 text-xs" :class="n===page?'bg-brand-green text-white':''" @click="page=n;load()">{{n}}</button><button class="rounded-full border px-3 py-1 text-xs" :disabled="page===pageCount" @click="page++;load()">Next</button></div></section><section class="rounded-2xl border border-neutral-line bg-white p-5"><div v-if="!selected" class="py-16 text-center text-sm text-neutral-charcoal/50">Klik artikel untuk melihat ringkasan detail.</div><div v-else><p class="text-xs font-semibold uppercase tracking-wider text-gold">Feedback artikel</p><h2 class="mt-2 font-heading text-xl font-semibold">{{selected.article.title}}</h2><p class="mt-2 text-sm text-neutral-charcoal/55">{{selected.article.city}} · {{selected.article.category}}</p><div class="mt-6 grid grid-cols-3 gap-2 text-center"><div class="rounded-xl bg-brand-green/10 p-3"><b class="block text-xl text-brand-green">{{selected.helpful}}</b><small>Helpful</small></div><div class="rounded-xl bg-red-50 p-3"><b class="block text-xl text-red-700">{{selected.notHelpful}}</b><small>Not helpful</small></div><div class="rounded-xl bg-neutral-soft p-3"><b class="block text-xl">{{selected.total}}</b><small>Total</small></div></div><p class="mt-5 text-center text-sm">Rasio helpful <b>{{selected.total?Math.round(selected.helpful/selected.total*100):0}}%</b></p></div></section></div></div></template>
